## Code Example
```javascript
// Example: redact PII in streaming payloads (simplified)
exports.handler = async (event) => {
  const redacted = event.records.map(r => {
    const payload = JSON.parse(Buffer.from(r.kinesis.data, 'base64').toString('utf-8'));
    payload.userEmail = 'REDACTED';
    payload.phone = payload.phone ? 'REDACTED' : payload.phone;
    return {
      ...r,
      body: JSON.stringify(payload)
    };
  });
  // forward redacted records to destination
  return { records: redacted };
};
```

